import React, { useState, useEffect } from "react";
import { useAuth } from "../context/AuthContext";
import { userAPI, petsAPI, adminAPI } from "../services/api";

// Helper function to get full image URL
const getImageUrl = (imagePath) => {
  if (!imagePath) return "/default-pet.png";
  if (imagePath.startsWith("http")) return imagePath;
  return `http://localhost:8000${imagePath}`;
};

const UserDashboard = () => {
  const [showProfileDropdown, setShowProfileDropdown] = useState(false);
  const { user } = useAuth();
  const [activeTab, setActiveTab] = useState("dashboard");
  const [lostReports, setLostReports] = useState([]);
  const [rescueReports, setRescueReports] = useState([]);
  const [allLostReports, setAllLostReports] = useState([]);
  const [availableAdoptionPets, setAvailableAdoptionPets] = useState([]);
  const [myAdoptionPosts, setMyAdoptionPosts] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [showNotifications, setShowNotifications] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [submitLoading, setSubmitLoading] = useState(false);
  const [successMessage, setSuccessMessage] = useState("");
  
  // Collapsible sections state
  const [expandedSection, setExpandedSection] = useState("lostReports");
  
  // Detail Modal state
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [selectedPetDetails, setSelectedPetDetails] = useState(null);
  const [detailLoading, setDetailLoading] = useState(false);

  const [profileData, setProfileData] = useState({
    first_name: "",
    last_name: "",
    email: "",
    phone_no: "",
    address: "",
    city: "",
    state: "",
    pincode: "",
    gender: "",
    profile_picture: null,
  });
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [profileImage, setProfileImage] = useState(null);
  const [profileImagePreview, setProfileImagePreview] = useState(null);
  // Only for navbar profile image
  const profileImageUrl = user?.profile_picture || null;

  // Pet report form state
  const [petForm, setPetForm] = useState({
    pet_name: "",
    pet_type: "Dog",
    pet_breed: "",
    pet_age: "",
    pet_colour: "",
    pet_weight: "",
    pet_gender: "Male",
    pet_location: "",
    pet_state: "",
    pet_city: "",
    pet_status: "lost",
    description: "",
    is_vaccinated: false,
    is_diseased: false,
    vaccination_details: "",
    health_conditions: "",
    pet_image: null,
  });

  // --- Dashboard Additions ---
  // Load user reports function
  const loadUserReports = async () => {
    try {
      const res = await userAPI.getUserReports();
      setLostReports(res.data.reports || []);
    } catch (err) {
      setError("Failed to load user reports.");
    }
  };
  // Forgot Password Section
  const [forgotEmail, setForgotEmail] = useState("");
  const [forgotPassword, setForgotPassword] = useState("");
  const [forgotConfirm, setForgotConfirm] = useState("");
  const [forgotMsg, setForgotMsg] = useState("");

  const handleForgotPassword = async (e) => {
    e.preventDefault();
    setForgotMsg("");
    try {
      const res = await userAPI.forgotPassword(
        forgotEmail,
        forgotPassword,
        forgotConfirm
      );
      setForgotMsg(res.data.message || "Password updated successfully.");
    } catch (err) {
      setForgotMsg(err.response?.data?.error || "Error resetting password.");
    }
  };

  // User Stories Section
  const [stories, setStories] = useState([]);
  const [storyContent, setStoryContent] = useState("");
  const [storyPetId, setStoryPetId] = useState("");
  const [storyMsg, setStoryMsg] = useState("");

  // Post Pet for Adoption Form
  const [postAdoptionForm, setPostAdoptionForm] = useState({
    name: "",
    type: "",
    breed: "",
    age: "",
    gender: "",
    description: "",
    location: "",
    image: null,
    is_vaccinated: false,
    is_diseased: false,
    disease_description: "",
    vaccination_date: "",
    vaccination_type: "",
    vaccination_certificate: null,
  });

  const loadStories = async () => {
    try {
      const res = await userAPI.getUserStories();
      setStories(res.data.stories || []);
    } catch {}
  };
  useEffect(() => {
    loadStories();
  }, []);

  const handlePostStory = async (e) => {
    e.preventDefault();
    setStoryMsg("");
    try {
      await userAPI.postUserStory(storyContent, storyPetId);
      setStoryMsg("Story posted!");
      setStoryContent("");
      setStoryPetId("");
      loadStories();
    } catch (err) {
      setStoryMsg("Error posting story.");
    }
  };

  // Favourite Pets Section
  const [favourites, setFavourites] = useState([]);
  const [favMsg, setFavMsg] = useState("");
  const loadFavourites = async () => {
    try {
      const res = await userAPI.getFavouritePets();
      setFavourites(res.data.favourites || []);
    } catch {}
  };
  useEffect(() => {
    loadFavourites();
  }, []);

  const handleAddFavourite = async (petId) => {
    setFavMsg("");
    try {
      await userAPI.addFavouritePet(petId);
      setFavMsg("Added to favourites.");
      loadFavourites();
    } catch (err) {
      setFavMsg("Error adding favourite.");
    }
  };

  const handleRemoveFavourite = async (favouriteId) => {
    setFavMsg("");
    try {
      await userAPI.removeFavouritePet(favouriteId);
      setFavMsg("Removed from favourites.");
      loadFavourites();
    } catch (err) {
      setFavMsg("Error removing favourite.");
    }
  };

  // --- Admin Dashboard Metrics Section ---
  const [adminMetrics, setAdminMetrics] = useState(null);
  const [metricsMsg, setMetricsMsg] = useState("");

  const loadAdminMetrics = async () => {
    setMetricsMsg("");
    try {
      const res = await adminAPI.getDashboardMetrics();
      setAdminMetrics(res.data.metrics || null);
    } catch (err) {
      setMetricsMsg("Error loading metrics.");
    }
  };
  // Call this in useEffect if user is admin
  // useEffect(() => { if (user?.role === 'admin') loadAdminMetrics(); }, [user]);
  // --- Example JSX ---
  /*
  {user?.role === 'admin' && adminMetrics && (
    <div className="admin-metrics">
      <h3>Admin Dashboard Metrics</h3>
      <ul>
        <li>Total Pets Reported: {adminMetrics.total_pets_reported}</li>
        <li>Total Adoptions Approved: {adminMetrics.total_adoptions_approved}</li>
        <li>Total Lost: {adminMetrics.total_lost}</li>
        <li>Total Found: {adminMetrics.total_found}</li>
        <li>Total Registered Users: {adminMetrics.total_registered_users}</li>
        <li>Total Cases Resolved: {adminMetrics.total_cases_resolved}</li>
      </ul>
      {metricsMsg && <div>{metricsMsg}</div>}
    </div>
  )}
  */

  // --- Placeholder for remaining REST APIs ---
  // TODO: Build Get All Registered Users API (Admin)
  // TODO: Build Pet Adoption Request API (if not already built)
  // TODO: Build Update Report Status API (Admin)
  // TODO: Build any other missing APIs from your requirements

  useEffect(() => {
    loadData();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const loadData = async () => {
    setLoading(true);
    setError("");
    try {
      // Load notifications
      await loadNotifications();

      // Load all lost reports for public viewing
      await loadAllLostReports();

      // Load available adoption pets
      await loadAvailableAdoptionPets();

      // Load my adoption posts
      await loadMyAdoptionPosts();

      // Load profile data
      await loadProfile();

      // Load real user reports from backend
      const reportsResponse = await userAPI.getUserReports();

      if (reportsResponse.data.success) {
        const { lost, found } = reportsResponse.data.reports;
        const mappedLostReports = lost.map((report) => ({
          ...report,
          photo: report.photo || getDefaultImage(report.animal_type),
        }));
        const mappedRescueReports = found.map((report) => ({
          ...report,
          photo: report.photo || getDefaultImage(report.animal_type),
        }));
        setLostReports(mappedLostReports);
        setRescueReports(mappedRescueReports);
      } else {
        setLostReports([]);
        setRescueReports([]);
      }
    } catch (err) {
      setError("Failed to load data. Please try again.");
      console.error("Error loading data:", err);

      // Set empty arrays on error
      setLostReports([]);
    }
    setLoading(false);
  };

  // Helper function to get default images based on pet type
  const getDefaultImage = (animalType) => {
    const defaultImages = {
      CAT: "https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=300&h=200&fit=crop",
      DOG: "https://images.unsplash.com/photo-1552053831-71594a27632d?w=300&h=200&fit=crop",
      BIRD: "https://images.unsplash.com/photo-1444464666168-49d633b86797?w=300&h=200&fit=crop",
      OTHER:
        "https://images.unsplash.com/photo-1425082661705-1834bfd09dca?w=300&h=200&fit=crop",
    };
    return defaultImages[animalType] || defaultImages["OTHER"];
  };

  const loadNotifications = async () => {
    try {
      const response = await userAPI.getUserNotifications();
      if (response.data.success) {
        const notificationData = response.data.notifications || [];
        setNotifications(notificationData);
        // Count unread notifications
        const unread = notificationData.filter(
          (notification) => !notification.is_read
        ).length;
        setUnreadCount(unread);
      }
    } catch (err) {
      console.error("Error loading notifications:", err);
    }
  };

  const loadAllLostReports = async () => {
    try {
      console.log("Loading all lost reports...");
      const response = await userAPI.getAllLostReports();
      console.log("All lost reports response:", response.data);

      if (response.data.success) {
        const reports = response.data.reports || [];
        console.log("Found", reports.length, "lost reports");
        setAllLostReports(reports);
      } else {
        console.error("API returned success=false:", response.data);
        setAllLostReports([]);
      }
    } catch (err) {
      console.error("Error loading all lost reports:", err);
      console.error("Error details:", err.response?.data);
      setAllLostReports([]);
    }
  };

  const loadAvailableAdoptionPets = async () => {
    try {
      console.log("Loading available adoption pets...");
      const response = await userAPI.getAvailableAdoptionPets();
      console.log("Available adoption pets response:", response.data);

      if (response.data.success) {
        const pets = response.data.pets || [];
        console.log("Found", pets.length, "available adoption pets");
        setAvailableAdoptionPets(pets);
      } else {
        console.error("API returned success=false:", response.data);
        setAvailableAdoptionPets([]);
      }
    } catch (err) {
      console.error("Error loading adoption pets:", err);
      console.error("Error details:", err.response?.data);
      setAvailableAdoptionPets([]);
    }
  };

  const loadMyAdoptionPosts = async () => {
    try {
      console.log("Loading my adoption posts...");
      const response = await petsAPI.getMyAdoptionPosts();
      console.log("My adoption posts response:", response.data);

      if (response.data.success) {
        const posts = response.data.adoption_posts || [];
        console.log("Found", posts.length, "adoption posts");
        setMyAdoptionPosts(posts);
      } else {
        console.error("API returned success=false:", response.data);
        setMyAdoptionPosts([]);
      }
    } catch (err) {
      console.error("Error loading my adoption posts:", err);
      console.error("Error details:", err.response?.data);
      setMyAdoptionPosts([]);
    }
  };

  const loadProfile = async () => {
    try {
      const response = await userAPI.getUserDetails();
      if (response.data.success) {
        const userData = response.data.user;
        setProfileData({
          first_name: userData.first_name || "",
          last_name: userData.last_name || "",
          email: userData.email || "",
          phone_no: userData.phone_no || "",
          address: userData.address || "",
          city: userData.city || "",
          state: userData.state || "",
          pincode: userData.pincode || "",
          gender: userData.gender || "",
          profile_picture: userData.profile_picture,
        });

        if (userData.profile_picture) {
          setProfileImagePreview(userData.profile_picture);
        }
      }
    } catch (err) {
      console.error("Error loading profile:", err);
    }
  };

  const handleProfileImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setProfileImage(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setProfileImagePreview(reader.result);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleProfileSubmit = async (e) => {
    e.preventDefault();
    setSubmitLoading(true);
    setError("");
    setSuccessMessage("");

    try {
      const formData = new FormData();
      Object.keys(profileData).forEach((key) => {
        if (key !== "profile_picture" && profileData[key]) {
          formData.append(key, profileData[key]);
        }
      });

      if (profileImage) {
        formData.append("profile_picture", profileImage);
      }

      const response = await userAPI.updateProfile(formData);
      if (response.data.success) {
        setSuccessMessage("Profile updated successfully!");
        setIsEditingProfile(false);
        await loadProfile(); // Reload profile data
      } else {
        setError(response.data.error || "Failed to update profile");
      }
    } catch (err) {
      setError(
        "Error updating profile: " + (err.response?.data?.error || err.message)
      );
    } finally {
      setSubmitLoading(false);
    }
  };

  const handleProfileInputChange = (e) => {
    const { name, value } = e.target;
    setProfileData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleNotificationDropdownToggle = () => {
    const newShowState = !showNotifications;
    setShowNotifications(newShowState);

    // Hide badge when opening dropdown
    if (newShowState) {
      setUnreadCount(0);
    }
  };

  const handleNotificationClick = async (notificationId) => {
    try {
      // Mark notification as read
      await userAPI.markNotificationRead(notificationId);

      // Update local state
      const updatedNotifications = notifications.map((notification) =>
        notification.id === notificationId
          ? { ...notification, is_read: true }
          : notification
      );
      setNotifications(updatedNotifications);

      // Update unread count
      const newUnreadCount = updatedNotifications.filter(
        (n) => !n.is_read
      ).length;
      setUnreadCount(newUnreadCount);
    } catch (err) {
      console.error("Error marking notification as read:", err);
    }
  };

  const handleDeleteNotification = async (notificationId) => {
    try {
      await userAPI.deleteNotification(notificationId);
      // Remove from local state
      const updatedNotifications = notifications.filter(
        (n) => n.id !== notificationId
      );
      setNotifications(updatedNotifications);
      // Recalculate unread count
      const unread = updatedNotifications.filter(
        (notification) => !notification.is_read
      ).length;
      setUnreadCount(unread);
    } catch (err) {
      console.error("Error deleting notification:", err);
    }
  };

  const handleDeleteReport = async (reportId) => {
    if (!window.confirm("Are you sure you want to delete this report?")) {
      return;
    }

    try {
      await userAPI.deleteReport(reportId);
      // Reload reports data
      await loadUserReports();
      setSuccessMessage("Report deleted successfully!");
      setTimeout(() => setSuccessMessage(""), 3000);
    } catch (err) {
      console.error("Error deleting report:", err);
      setError("Failed to delete report. Please try again.");
      setTimeout(() => setError(""), 3000);
    }
  };

  const handleReuniteReport = async (reportId) => {
    if (!window.confirm("Mark this pet as reunited with owner?")) {
      return;
    }

    try {
      await userAPI.updateReportStatus(reportId, "reunited");
      // Reload reports data
      await loadUserReports();
      setSuccessMessage("Pet marked as reunited! 🎉");
      setTimeout(() => setSuccessMessage(""), 3000);
    } catch (err) {
      console.error("Error reuniting report:", err);
      setError("Failed to update report. Please try again.");
      setTimeout(() => setError(""), 3000);
    }
  };

  // Fetch full pet details for modal
  const fetchPetDetails = async (petId) => {
    console.log("Fetching details for pet ID:", petId);
    setDetailLoading(true);
    setShowDetailModal(true);
    setSelectedPetDetails(null);
    
    try {
      const response = await petsAPI.getPetDetails(petId);
      console.log("Pet details API response:", response);
      console.log("Response data:", response.data);
      
      // Check different possible response structures
      if (response.data && response.data.success && response.data.pet_details) {
        console.log("Setting pet details:", response.data.pet_details);
        setSelectedPetDetails(response.data.pet_details);
      } else if (response.data && response.data.pet_details) {
        console.log("Setting pet details (no success flag):", response.data.pet_details);
        setSelectedPetDetails(response.data.pet_details);
      } else if (response.success && response.pet_details) {
        console.log("Setting pet details (direct):", response.pet_details);
        setSelectedPetDetails(response.pet_details);
      } else {
        console.error("Failed to parse pet details response:", response);
        setError("Failed to load pet details - Invalid response format");
        setTimeout(() => setError(""), 3000);
        setShowDetailModal(false);
      }
    } catch (err) {
      console.error("Error fetching pet details:", err);
      console.error("Error response:", err.response);
      setError(`Failed to load pet details: ${err.response?.data?.error || err.message}`);
      setTimeout(() => setError(""), 5000);
      setShowDetailModal(false);
    } finally {
      setDetailLoading(false);
    }
  };

  const closeDetailModal = () => {
    setShowDetailModal(false);
    setSelectedPetDetails(null);
  };

  const handleMarkReport = async (reportId, status) => {
    try {
      await userAPI.updateReportStatus(reportId, status);
      // Reload reports data
      await loadUserReports();
      setSuccessMessage(`Report marked as ${status.toLowerCase()}!`);
      setTimeout(() => setSuccessMessage(""), 3000);
    } catch (err) {
      console.error("Error updating report status:", err);
      setError("Failed to update report status. Please try again.");
      setTimeout(() => setError(""), 3000);
    }
  };

  const handleFormChange = (e) => {
    const { name, value, type, checked } = e.target;
    setPetForm((prev) => ({
      ...prev,
      [name]: type === "checkbox" ? checked : value,
    }));
  };

  const handleSubmitPetReport = async (e) => {
    e.preventDefault();
    setSubmitLoading(true);
    setError("");
    setSuccessMessage("");

    try {
      // Create FormData for file upload
      const formData = new FormData();

      // Add all form fields
      Object.keys(petForm).forEach((key) => {
        if (key === "pet_image" && petForm[key]) {
          formData.append("pet_image", petForm[key]);
        } else if (key !== "pet_image") {
          formData.append(key, petForm[key]);
        }
      });

      const response = await petsAPI.submitPetRequestWithImage(formData);
      if (response.data.success) {
        setSuccessMessage(
          `${
            petForm.pet_status.charAt(0).toUpperCase() +
            petForm.pet_status.slice(1)
          } pet report submitted successfully!`
        );
        // Reset form
        setPetForm({
          pet_name: "",
          pet_type: "Dog",
          pet_breed: "",
          pet_age: "",
          pet_colour: "",
          pet_weight: "",
          pet_gender: "Male",
          pet_location: "",
          pet_state: "",
          pet_city: "",
          pet_status: "lost",
          description: "",
          is_vaccinated: false,
          is_diseased: false,
          vaccination_details: "",
          health_conditions: "",
          pet_image: null,
        });
        // Reload data to show updated reports
        await loadData();
        // Switch back to dashboard tab
        setTimeout(() => {
          setActiveTab("dashboard");
        }, 2000);
      }
    } catch (err) {
      setError(
        err.response?.data?.error ||
          "Failed to submit pet report. Please try again."
      );
    }
    setSubmitLoading(false);
  };

  const handlePostPetForAdoption = async (e) => {
    e.preventDefault();
    setSubmitLoading(true);
    setError("");
    setSuccessMessage("");

    try {
      const formData = new FormData();
      formData.append("name", postAdoptionForm.name);
      formData.append("type", postAdoptionForm.type);
      formData.append("breed", postAdoptionForm.breed);
      formData.append("age", postAdoptionForm.age);
      formData.append("gender", postAdoptionForm.gender);
      formData.append("description", postAdoptionForm.description);
      formData.append("location", postAdoptionForm.location);
      formData.append("is_vaccinated", postAdoptionForm.is_vaccinated);
      formData.append("is_diseased", postAdoptionForm.is_diseased);

      if (postAdoptionForm.is_diseased) {
        formData.append(
          "disease_description",
          postAdoptionForm.disease_description
        );
      }

      if (postAdoptionForm.is_vaccinated) {
        formData.append("vaccination_date", postAdoptionForm.vaccination_date);
        formData.append("vaccination_type", postAdoptionForm.vaccination_type);
        if (postAdoptionForm.vaccination_certificate) {
          formData.append(
            "vaccination_certificate",
            postAdoptionForm.vaccination_certificate
          );
        }
      }

      if (postAdoptionForm.image) {
        formData.append("image", postAdoptionForm.image);
      }

      const response = await petsAPI.postPetForAdoption(formData);

      if (response.data.success) {
        setSuccessMessage(response.data.message);
        // Reset form
        setPostAdoptionForm({
          name: "",
          type: "",
          breed: "",
          age: "",
          gender: "",
          description: "",
          location: "",
          image: null,
          is_vaccinated: false,
          is_diseased: false,
          disease_description: "",
          vaccination_date: "",
          vaccination_type: "",
          vaccination_certificate: null,
        });
        // Reload data
        await loadData();
        // Clear success message after 5 seconds
        setTimeout(() => setSuccessMessage(""), 5000);
      }
    } catch (err) {
      setError(
        err.response?.data?.error ||
          "Failed to post pet for adoption. Please try again."
      );
    }
    setSubmitLoading(false);
  };

  const renderReportCard = (report) => (
    <div key={report.id} className="dashboard-pet-card">
      <div className="pet-card-image">
        <img
          src={report.photo}
          alt={report.pet_name}
          onError={(e) => {
            e.target.src = getDefaultImage(report.animal_type);
          }}
        />
        <div className="pet-name-overlay">
          <h3>{report.pet_name}</h3>
        </div>
      </div>
      <div className="pet-card-info">
        <div className="pet-type">{report.animal_type}</div>
        <div className="pet-details">
          {report.pet_breed && (
            <span className="pet-breed">{report.pet_breed}</span>
          )}
          {report.pet_location && (
            <span className="pet-location">📍 {report.pet_location}</span>
          )}
        </div>
        <div className="pet-description">
          {report.description
            ? report.description.length > 50
              ? `${report.description.substring(0, 50)}...`
              : report.description
            : "No description available"}
        </div>
        <div className="report-meta">
          <span className="report-date">
            {new Date(report.created_at).toLocaleDateString()}
          </span>
        </div>
        <div className={`pet-status-badge ${report.status.toLowerCase()}`}>
          {report.status}
        </div>
        <div className="report-actions">
          {report.status !== "FOUND" && report.status !== "REUNITED" && (
            <div className="mark-buttons">
              {report.report_type === "LOST" && report.status !== "FOUND" && (
                <button
                  className="btn-mark-found"
                  onClick={() => handleMarkReport(report.id, "FOUND")}
                  title="Mark as Found"
                >
                  <span className="material-icons">check_circle</span>
                  Found
                </button>
              )}
              {report.status !== "REUNITED" && (
                <button
                  className="btn-mark-reunited"
                  onClick={() => handleMarkReport(report.id, "REUNITED")}
                  title="Mark as Reunited"
                >
                  <span className="material-icons">favorite</span>
                  Reunited
                </button>
              )}
            </div>
          )}
          <button
            className="btn-delete-report"
            onClick={() => handleDeleteReport(report.id)}
            title="Delete Report"
          >
            <span className="material-icons">delete</span>
          </button>
        </div>
      </div>
    </div>
  );

  const renderPublicReportCard = (report) => (
    <div key={report.id} className="dashboard-pet-card public-report">
      <div className="pet-card-image">
        <img
          src={report.photo}
          alt={report.pet_name}
          onError={(e) => {
            e.target.src = getDefaultImage(report.animal_type);
          }}
        />
        <div className="pet-name-overlay">
          <h3>{report.pet_name}</h3>
        </div>
      </div>
      <div className="pet-card-info">
        <div className="pet-type">{report.animal_type}</div>
        <div className="pet-details">
          {report.pet_breed && (
            <span className="pet-breed">{report.pet_breed}</span>
          )}
          {report.pet_location && (
            <span className="pet-location">📍 {report.pet_location}</span>
          )}
        </div>
        <div className="pet-description">
          {report.description
            ? report.description.length > 80
              ? `${report.description.substring(0, 80)}...`
              : report.description
            : "No description available"}
        </div>
        <div className="report-meta">
          <span className="report-date">
            {new Date(report.created_at).toLocaleDateString()}
          </span>
          <span className="report-owner">
            By: {report.owner_username || "Anonymous"}
          </span>
        </div>
        <div className={`pet-status-badge ${report.status.toLowerCase()}`}>
          {report.status}
        </div>
        <div className="contact-info">
          {report.contact_info && (
            <div className="contact-details">
              <span className="material-icons">contact_phone</span>
              <span className="contact-text">Contact owner for details</span>
            </div>
          )}
        </div>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-blue-50">
      <header className="sticky top-0 z-50 backdrop-blur-md bg-gradient-to-r from-slate-50/95 to-blue-50/95 shadow-lg border-b border-blue-200">
        <div className="max-w-full mx-auto px-6 py-4">
          <div className="flex items-center justify-between gap-4">
            <div className="flex items-center gap-3">
              <div className="text-2xl font-bold bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                PET_RESCUE_APP
              </div>
            </div>
            <div className="flex-1 text-center">
              <span className="text-lg font-semibold text-primary-blue">
                WELCOME: {user?.username?.toUpperCase() || "USER_NAME"}
              </span>
            </div>
            <div className="flex items-center gap-4">
              <button
                className="p-2 rounded-full hover:bg-blue-100 transition-all duration-300 disabled:opacity-50"
                onClick={loadData}
                disabled={loading}
                title="Refresh Data"
              >
                <span className="material-icons text-primary-blue">
                  refresh
                </span>
              </button>
              <div className="relative">
                <button
                  className="p-2 rounded-full hover:bg-blue-100 transition-all duration-300 relative"
                  onClick={handleNotificationDropdownToggle}
                >
                  <span className="material-icons text-primary-blue">
                    notifications
                  </span>
                  {unreadCount > 0 && !showNotifications && (
                    <span className="absolute -top-1 -right-1 bg-red-500 text-white text-xs font-bold rounded-full w-5 h-5 flex items-center justify-center">
                      {unreadCount}
                    </span>
                  )}
                </button>
                {showNotifications && (
                  <div className="absolute right-0 mt-2 w-96 bg-gradient-to-br from-slate-50 to-blue-50 rounded-2xl shadow-2xl border border-blue-200 overflow-hidden z-50 max-h-[500px] flex flex-col">
                    <div className="flex items-center justify-between p-4 bg-gradient-to-r from-primary-blue to-primary-teal border-b border-blue-200">
                      <h3 className="text-white font-semibold text-lg">
                        Notifications
                      </h3>
                      <button
                        className="text-white hover:bg-white/20 rounded-full p-1 transition-colors"
                        onClick={(e) => {
                          e.stopPropagation();
                          setShowNotifications(false);
                        }}
                      >
                        <span className="text-2xl leading-none">×</span>
                      </button>
                    </div>
                    <div className="overflow-y-auto flex-1">
                      {notifications.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-12 text-gray-400">
                          <span className="material-icons text-6xl mb-2">
                            notifications_none
                          </span>
                          <p className="text-sm">No notifications yet</p>
                        </div>
                      ) : (
                        notifications.map((notification) => (
                          <div
                            key={notification.id}
                            className={`p-4 border-b border-blue-100 hover:bg-blue-100 transition-colors cursor-pointer ${
                              notification.is_read
                                ? "bg-slate-50"
                                : "bg-blue-50/50"
                            }`}
                            onClick={() =>
                              handleNotificationClick(notification.id)
                            }
                          >
                            <div className="flex items-start justify-between gap-3">
                              <div className="flex-1">
                                <h4
                                  className={`font-semibold text-sm ${
                                    notification.is_read
                                      ? "text-gray-600"
                                      : "text-primary-blue"
                                  }`}
                                >
                                  {notification.title}
                                </h4>
                                <p className="text-gray-600 text-sm mt-1">
                                  {notification.message}
                                </p>
                                <span className="text-xs text-gray-400 mt-2 block">
                                  {new Date(
                                    notification.created_at
                                  ).toLocaleDateString()}
                                </span>
                              </div>
                              <button
                                className="p-1 hover:bg-red-100 rounded-full transition-colors"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  handleDeleteNotification(notification.id);
                                }}
                              >
                                <span className="material-icons text-red-500 text-lg">
                                  delete
                                </span>
                              </button>
                            </div>
                          </div>
                        ))
                      )}
                    </div>
                  </div>
                )}
              </div>
              <div className="relative">
                <button
                  className="w-10 h-10 rounded-full bg-gradient-to-br from-primary-blue to-primary-teal text-white font-bold text-lg flex items-center justify-center hover:shadow-lg transition-all duration-300 hover:scale-110"
                  onClick={() => setShowProfileDropdown((prev) => !prev)}
                >
                  {user?.username?.charAt(0).toUpperCase() || "U"}
                </button>
                {showProfileDropdown && (
                  <div className="absolute right-0 mt-2 w-48 bg-gradient-to-br from-slate-50 to-blue-50 rounded-xl shadow-xl border border-blue-200 overflow-hidden z-50">
                    <button
                      className="w-full px-4 py-3 text-left hover:bg-blue-100 transition-colors text-gray-700 hover:text-primary-blue font-medium"
                      onClick={() => {
                        setActiveTab("profile");
                        setShowProfileDropdown(false);
                      }}
                    >
                      Edit Profile
                    </button>
                    <button
                      className="w-full px-4 py-3 text-left hover:bg-red-50 transition-colors text-red-600 hover:text-red-700 font-medium border-t border-gray-100"
                      onClick={() => {
                        // Clear token from localStorage
                        localStorage.removeItem("token");

                        // Optionally clear other user-related data
                        // localStorage.removeItem('user');

                        // Redirect to login page
                        window.location.href = "/login";
                      }}
                    >
                      Logout
                    </button>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
        {/* Horizontal Navigation Bar */}
        <nav className="bg-gradient-to-r from-primary-blue via-primary-teal to-primary-teal border-t border-blue-200">
