                      </label>
                      <input
                        type="text"
                        value={postAdoptionForm.name}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            name: e.target.value,
                          })
                        }
                        required
                        className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors"
                        placeholder="Enter pet name"
                      />
                    </div>
                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 mb-2">
                        Pet Type *
                      </label>
                      <select
                        value={postAdoptionForm.type}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            type: e.target.value,
                          })
                        }
                        required
                        className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors bg-slate-50/50"
                      >
                        <option value="">Select Type</option>
                        <option value="Dog">Dog</option>
                        <option value="Cat">Cat</option>
                        <option value="Bird">Bird</option>
                        <option value="Rabbit">Rabbit</option>
                        <option value="Other">Other</option>
                      </select>
                    </div>

                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 mb-2">
                        Breed
                      </label>
                      <input
                        type="text"
                        value={postAdoptionForm.breed}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            breed: e.target.value,
                          })
                        }
                        className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors"
                        placeholder="Enter breed"
                      />
                    </div>
                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 mb-2">
                        Age (years) *
                      </label>
                      <input
                        type="number"
                        min="0"
                        value={postAdoptionForm.age}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            age: e.target.value,
                          })
                        }
                        required
                        className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors"
                        placeholder="Age in years"
                      />
                    </div>

                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 mb-2">
                        Gender *
                      </label>
                      <select
                        value={postAdoptionForm.gender}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            gender: e.target.value,
                          })
                        }
                        required
                        className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors bg-slate-50/50"
                      >
                        <option value="">Select Gender</option>
                        <option value="Male">Male</option>
                        <option value="Female">Female</option>
                      </select>
                    </div>
                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 mb-2">
                        Location *
                      </label>
                      <input
                        type="text"
                        value={postAdoptionForm.location}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            location: e.target.value,
                          })
                        }
                        required
                        className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors"
                        placeholder="Current location"
                      />
                    </div>
                  </div>

                  <div className="flex flex-col mb-6">
                    <label className="text-sm font-semibold text-gray-700 mb-2">
                      Description
                    </label>
                    <textarea
                      rows="4"
                      value={postAdoptionForm.description}
                      onChange={(e) =>
                        setPostAdoptionForm({
                          ...postAdoptionForm,
                          description: e.target.value,
                        })
                      }
                      className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors resize-none"
                      placeholder="Describe your pet's temperament, habits, and why they're great for adoption..."
                    />
                  </div>

                  <div className="flex flex-col mb-6">
                    <label className="text-sm font-semibold text-gray-700 mb-2">
                      Pet Image
                    </label>
                    <input
                      type="file"
                      accept="image/*"
                      onChange={(e) =>
                        setPostAdoptionForm({
                          ...postAdoptionForm,
                          image: e.target.files[0],
                        })
                      }
                      className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-primary-blue file:text-white hover:file:bg-primary-teal file:cursor-pointer"
                    />
                  </div>

                  <h3 className="text-lg font-bold text-gray-800 mb-4 flex items-center gap-2">
                    <span className="text-2xl">💊</span>
                    Medical Information
                  </h3>

                  <div className="space-y-4 mb-6">
                    <div className="flex items-center gap-3 p-4 bg-gray-50 rounded-xl hover:bg-gray-100 transition-colors">
                      <input
                        type="checkbox"
                        checked={postAdoptionForm.is_vaccinated}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            is_vaccinated: e.target.checked,
                          })
                        }
                        className="w-5 h-5 rounded border-2 border-gray-300 text-primary-blue focus:ring-2 focus:ring-primary-blue focus:ring-offset-2 cursor-pointer"
                      />
                      <label className="text-sm font-medium text-gray-700 cursor-pointer select-none">
                        Is Vaccinated
                      </label>
                    </div>

